    @GameTest(environment="buildupmobtweaks:r4c",structure=ARENA,maxTicks=65)
    public void actualFinalizeSpawnSamplesExclusiveDefaultTraitsWithoutReroll(GameTestHelper h){int fire=0,totem=0;for(int i=0;i<1000;i++){var m=EntityTypes.EVOKER.create(h.getLevel(),EntitySpawnReason.NATURAL);m.finalizeSpawn(h.getLevel(),h.getLevel().getCurrentDifficultyAt(h.absolutePos(BlockPos.ZERO)),EntitySpawnReason.NATURAL,null);String birth=m.getAttached(RaidState.EVOKER).getStringOr("birth","missing");if(birth.equals("fireball"))fire++;else if(birth.equals("totem"))totem++;else h.assertTrue(birth.equals("none"),"Only known exclusive outcomes");var copy=m.getAttached(RaidState.EVOKER).copy();m.finalizeSpawn(h.getLevel(),h.getLevel().getCurrentDifficultyAt(h.absolutePos(BlockPos.ZERO)),EntitySpawnReason.SPAWN_ITEM_USE,null);h.assertTrue(copy.equals(m.getAttached(RaidState.EVOKER)),"Repeated native finalizeSpawn does not reroll");m.discard();}
        h.assertTrue(fire>30&&fire<120&&totem>0&&totem<35,"Default weighted fixture sample is consistent with 70/10 per thousand");BuildupMobTweaks.LOGGER.info("R4C_EVIDENCE scenario=E01_E02_default_birth n=1000 fireball={} totem={} native_finalizeSpawn=true natural_spawner=NOT_RUN",fire,totem);h.succeed();}
    @GameTest(environment="buildupmobtweaks:r4c",structure=ARENA,maxTicks=280)
    public void witchNativeRaidAllyHealingBypassesHostilePreviewAndCooldown(GameTestHelper h){SkeletonBehaviorTests.floor(h,false);var m=mob(h,EntityTypes.WITCH);var ally=EntityTypes.PILLAGER.create(h.getLevel(),EntitySpawnReason.COMMAND);ally.snapTo(h.absolutePos(new BlockPos(8,2,15)),0,0);ally.setNoAi(true);ally.setHealth(3);ally.addTag("buildupmobtweaks:vanilla_ai");h.getLevel().addFreshEntity(ally);
        // Directed native active-Raid membership, not a complete village raid or a direct Goal call.
        var raid=new net.minecraft.world.entity.raid.Raid(m.blockPosition(),h.getLevel().getDifficulty());m.setCurrentRaid(raid);ally.setCurrentRaid(raid);m.getAttached(RaidState.WITCH).putLong("throw_ready",h.getLevel().getGameTime()+10000);
        boolean[] healed={false};h.onEachTick(()->{if(ally.getHealth()>3)healed[0]=true;});
        h.runAtTickTime(250,()->{h.assertTrue(healed[0]&&RaidState.runtime(m).throwsMade>0&&RaidState.runtime(m).previews==0,"Native heal-raider selector, actual potion and ally healing bypass hostile cooldown and preview");proof("W01_limited_raid_heal",m,"allyHealth="+ally.getHealth()+" full_raid=NOT_RUN");m.setCurrentRaid(null);ally.setCurrentRaid(null);raid.stop();m.discard();ally.discard();h.succeed();});}
