    @GameTest(environment="buildupmobtweaks:r4c",structure=ARENA,maxTicks=105)
    public void actualBlockImpactNoFireThenIndependentGateRestoresFire(GameTestHelper h){SkeletonBehaviorTests.floor(h,false);for(int x=6;x<=10;x++)for(int y=2;y<=4;y++)h.setBlock(new BlockPos(x,y,14),net.minecraft.world.level.block.Blocks.STONE);var m=evoker(h,"fireball");m.setNoAi(true);
        java.util.function.Supplier<SmallFireball> launch=()->{var b=new SmallFireball(h.getLevel(),m,new net.minecraft.world.phys.Vec3(0,0,1));var d=new CompoundTag();d.putInt("version",1);d.putLong("expires",h.getLevel().getGameTime()+200);b.setAttached(RaidState.BALL,d);b.snapTo(m.position().add(0,.3,2),0,0);h.getLevel().addFreshEntity(b);return b;};var first=launch.get();SmallFireball[] second={null};
        h.runAtTickTime(35,()->{h.assertTrue(first.isRemoved()&&h.getLevel().getBlockState(h.absolutePos(new BlockPos(8,2,13))).isAir(),"Actual block collision discarded first own fireball without placing fire");m.addTag("buildupmobtweaks:disable_evoker_fireball_no_fire");second[0]=launch.get();});
        h.runAtTickTime(80,()->{h.assertTrue(second[0].isRemoved()&&h.getLevel().getBlockState(h.absolutePos(new BlockPos(8,2,13))).is(net.minecraft.world.level.block.Blocks.FIRE),"Independent no-fire off restores actual native terrain ignition under mobGriefing");proof("E01_block_impact",m,"no_fire_then_native_fire=true");clean(m);h.succeed();});}
